if(!EditorApplication.isPlaying||string.IsNullOrEmpty(SessionState.GetString("Bulldozer.Mining.TestSavePath","")))throw new System.Exception("Isolated play required");
var rounds=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.ExcavationRounds>();var p=rounds.player;var e=rounds.equipment;var prod=rounds.production;var upgrade=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MinerUpgradeArea>();var mining=p.visual.GetComponent<Bulldozer.Player.MinerMining>();var rocks=UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(FindObjectsSortMode.None).OrderBy(r=>r.transform.position.z).ThenBy(r=>r.transform.position.x).ToArray();
var report=new System.Collections.Generic.List<string>();System.Action<bool,string> check=(ok,msg)=>report.Add((ok?"PASS ":"FAIL ")+msg);check(e.Cash==0&&e.CargoCount==0&&e.RoundIndex==0,"Fresh isolated start");
p.autoMine=false;p.CancelMining();p.touchControls.Move=Vector2.zero;string activity="",target="";float changed=Time.time,began=Time.time;int frame=Time.frameCount,startHits=mining.SuccessfulHits;bool firstUpgrade=false,speed=false,rack=false;int sold=0;var lastFirstPhase=prod.delivery.Phase;var lastSecondPhase=prod.secondDelivery.Phase;bool firstDispatched=false,secondDispatched=false;float minGap=1000;int expectedItems=rocks.Length*3;
System.Action<Vector3> place=pos=>{p.autoMine=false;p.CancelMining();var cc=p.GetComponent<CharacterController>();cc.enabled=false;pos.y=.03f;p.transform.position=pos;cc.enabled=true;p.visual.rotation=Quaternion.identity;Physics.SyncTransforms();e.drops.ResetPickupSweep();};
System.Action<string,string,Vector3> go=(a,id,pos)=>{if(activity==a&&target==id)return;activity=a;target=id;changed=Time.time;place(pos);};
EditorApplication.isPaused=false;Time.captureDeltaTime=1f/30;Application.targetFrameRate=120;QualitySettings.vSyncCount=0;EditorApplication.CallbackFunction tick=null;
System.Action<string> finish=reason=>{report.Add(reason);System.IO.File.WriteAllLines("Maintenance/Miner/full-loop-verification.txt",report);EditorApplication.update-=tick;Time.captureDeltaTime=0;p.autoMine=false;p.CancelMining();};
tick=()=>{if(!EditorApplication.isPlaying){EditorApplication.update-=tick;return;}try{
 if(prod.delivery.Phase==Bulldozer.Player.TruckDelivery.DeliveryPhase.Loading)firstDispatched=true;if(prod.secondDelivery.Phase==Bulldozer.Player.TruckDelivery.DeliveryPhase.Loading)secondDispatched=true;
 if(prod.delivery.Phase==Bulldozer.Player.TruckDelivery.DeliveryPhase.Loading&&lastFirstPhase!=prod.delivery.Phase)sold+=prod.delivery.loadedCount; if(prod.secondDelivery.Phase==Bulldozer.Player.TruckDelivery.DeliveryPhase.Loading&&lastSecondPhase!=prod.secondDelivery.Phase)sold+=prod.secondDelivery.loadedCount;lastFirstPhase=prod.delivery.Phase;lastSecondPhase=prod.secondDelivery.Phase;
 if(prod.delivery.body.enabled&&prod.secondDelivery.body.enabled)minGap=Mathf.Min(minGap,Vector3.Distance(prod.delivery.transform.position,prod.secondDelivery.transform.position));
 if(Time.frameCount-frame<12){if(EditorApplication.isPaused)EditorApplication.Step();return;}frame=Time.frameCount;var s=e.Snapshot;
 System.IO.File.WriteAllText("Maintenance/Miner/full-loop-status.txt",$"t={Time.time-began:F1} activity={activity} target={target} broken={s.depletedBlocks.Length}/{rocks.Length} hits={mining.SuccessfulHits} drops={s.groundDrops.Length} cargo={s.items.Length} input={s.refineryInput.Length} output={s.refineryOutput.Length} queue={s.loadingQueue.Length} truck={s.truckItems.Length} deliveries={s.trucksCompleted} sold={sold} cash={s.coins} pos={p.transform.position} mining={mining.Status}");
 if(s.roundBonusClaimed){check(s.depletedBlocks.Length==rocks.Length,"All 78 rocks broken by animation contact");check(mining.SuccessfulHits>78,"Repeated animated strikes exercised");check(Bulldozer.Player.Persistence.ExcavationRules.CargoSettled(s),"All ground, carried, refinery and truck inventory settled");check(s.taskRefined==expectedItems,"Every mined item refined once: "+s.taskRefined);check(sold==expectedItems,"Every refined item sold once: "+sold);check(firstDispatched&&secondDispatched,"Both trucks dispatched through the shared lane");check(minGap>=4.8f,"Truck separation stays safe: "+minGap);check(firstUpgrade&&speed&&rack,"Earned-cash pickaxe, rack and speed purchases completed");var cash=e.Cash;check(!rounds.TryComplete()&&e.Cash==cash,"Completion bonus cannot pay twice");SessionState.SetString("Loop.Expected",JsonUtility.ToJson(s));finish("PASS Round complete; ready for restart and next-round verification");return;}
 if(Time.time-began>1500||Time.time-changed>50){finish("FAIL timeout at "+activity+" "+target+" status="+mining.Status);return;}
 if(!firstUpgrade&&e.Cash>=e.DamageCost){go("upgrade","pickaxe",upgrade.zone.bounds.center);if(Time.time-changed>.5f){check(upgrade.Purchase(false),"First pickaxe bought with earned starter reward");firstUpgrade=e.DamageLevel==1;activity="";} }
 else if(firstUpgrade&&!speed&&e.Cash>=e.SpeedCost){go("upgrade","speed",upgrade.zone.bounds.center);if(Time.time-changed>.5f){speed=upgrade.PurchaseSpeed();check(speed,"Speed purchase with earned delivery cash");activity="";} }
 else if(firstUpgrade&&speed&&!rack&&e.Cash>=e.CapacityCost){go("upgrade","rack",upgrade.zone.bounds.center);if(Time.time-changed>.5f){rack=upgrade.Purchase(true);check(rack,"Rack purchase with earned delivery cash");activity="";} }
 else if(s.items.Any(id=>id>=6)){go("load","",prod.sellZone.bounds.center);}
 else if(s.items.Length>0){go("deposit","",prod.inputZone.bounds.center);}
 else if(s.refineryOutput.Length>0){go("collect","",prod.outputZone.bounds.center);}
 else if(s.groundDrops.Length>0){var d=s.groundDrops[0];go("pickup",d.id,d.position);}
 else {var r=rocks.FirstOrDefault(r=>!r.Depleted);if(r){var pos=r.naturalBoulder?r.transform.position-Vector3.forward*1.05f:new Vector3(r.HitCollider.bounds.center.x,.03f,r.HitCollider.bounds.min.z-.65f);go("mine",r.blockId,pos);if(Time.time-changed>.5f)p.autoMine=true;}else go("drain","",new Vector3(0,.03f,-3));}
 if(EditorApplication.isPaused)EditorApplication.Step();
 }catch(System.Exception ex){finish("FAIL "+ex);}};EditorApplication.update+=tick;return "Full loop running: actual animated hits, pickup triggers, production timers, station transfers and deliveries";


